import os, fnmatch

def decode_source_name(name):
    if name.startswith('dot_'): name='.'+name[4:]
    elif name.startswith('private_'): name=name[8:]
    elif name.startswith('executable_'): name=name[11:]
    elif name.startswith('readonly_'): name=name[9:]
    elif name.startswith('symlink_'): name=name[8:]
    if name.endswith('.tmpl'): name=name[:-5]
    return name

def managed(source, destination, args):
    source=os.path.abspath(os.path.expanduser(source)); destination=os.path.abspath(os.path.expanduser(destination))
    excludes=set(); includes=None; style='relative'; tree=False; nul=False; paths=[]
    i=0
    while i<len(args):
        a=args[i]
        if a in ('-i','--include','-x','--exclude','-p','--path-style','-f','--format'):
            i+=1
            if i>=len(args): return 0,''
            v=args[i]
            if a in ('-i','--include'): includes=set(v.split(','))
            elif a in ('-x','--exclude'): excludes.update(v.split(','))
            elif a in ('-p','--path-style'): style=v
        elif a.startswith('--include='): includes=set(a.split('=',1)[1].split(','))
        elif a.startswith('--exclude='): excludes.update(a.split('=',1)[1].split(','))
        elif a.startswith('--path-style='): style=a.split('=',1)[1]
        elif a in ('-t','--tree'): tree=True
        elif a in ('-0','--nul-path-separator'): nul=True
        elif a.startswith('-'): pass
        else: paths.append(a)
        i+=1
    ignored=[]
    try:
        with open(os.path.join(source,'.chezmoiignore')) as f:
            ignored=[line.strip() for line in f if line.strip() and not line.lstrip().startswith('#')]
    except OSError: pass
    entries=[]
    for root,dirs,files in os.walk(source):
        dirs[:]=[d for d in dirs if not d.startswith('.chezmoi')]
        for n in files:
            rel=os.path.relpath(os.path.join(root,n),source)
            if n.startswith('.chezmoi') or any(fnmatch.fnmatch(rel,g) or fnmatch.fnmatch(decode_source_name(rel),g) for g in ignored): continue
            target=decode_source_name(rel)
            kind='symlinks' if n.startswith('symlink_') else 'files'
            if includes is not None and kind not in includes: continue
            if kind in excludes: continue
            if paths and not any(target==p or target.startswith(p.rstrip('/')+'/') for p in paths): continue
            entries.append((target,rel))
    entries.sort()
    out=[]
    for target,rel in entries:
        if style=='source-relative': out.append(rel)
        elif style=='source-absolute': out.append(os.path.join(source,rel))
        elif style=='absolute': out.append(os.path.join(destination,target))
        elif style=='all': out.append(os.path.join(destination,target))
        else: out.append(target)
    return 0, ('\0' if nul else '\n').join(out)+(('\0' if nul else '\n') if out else '')
