def validate_flags(command, args):
    """Return a Cobra-like error tuple for an unrecognized command flag."""
    from command_help import COMMAND_HELP
    import re
    if command == 'git' and '--' in args:
        args = args[:args.index('--')]
    entry = COMMAND_HELP.get(command)
    if entry is None:
        return None
    text = entry[1]
    allowed_long = set(re.findall(r'^\s*(?:-[A-Za-z],\s*)?--([A-Za-z0-9-]+)', text, re.M))
    allowed_short = set(re.findall(r'^\s*-([A-Za-z]),\s*--', text, re.M))
    global_long = set(re.findall(r'^\s*(?:-[A-Za-z],\s*)?--([A-Za-z0-9-]+)', ROOT_HELP, re.M))
    global_short = set(re.findall(r'^\s*-([A-Za-z]),\s*--', ROOT_HELP, re.M))
    known_long = allowed_long | global_long
    known_short = allowed_short | global_short
    for arg in args:
        if arg.startswith('--'):
            name = arg[2:].split('=', 1)[0]
