"""Run a Git invocation in chezmoi's configured working tree."""
import os
import subprocess


def handle(args, source, working_tree=None):
    cwd = os.path.abspath(os.path.expanduser(working_tree or source))
    if not os.path.isdir(cwd):
        try:
            os.makedirs(cwd, exist_ok=True)
        except OSError as e:
            return 1, '', f'chezmoi: mkdir {cwd}: {e.strerror or e}\n'
    if '--' in args:
        args = args[args.index('--') + 1:]
    try:
        p = subprocess.run(['git'] + list(args), cwd=cwd, capture_output=True, text=True)
    except OSError as e:
        return 1, '', f'chezmoi: git: {e}\n'
    if p.returncode:
        return 1, p.stdout, p.stderr + f'chezmoi: git: exit status {p.returncode}\n'
