"""Load JSON, YAML-subset, and TOML-subset chezmoi data files."""
import json, os, re

def _scalar(s):
    s=s.strip()
    if not s:return None
    if s.startswith('"') and s.endswith('"'):
        try:return json.loads(s)
        except ValueError:return s[1:-1]
    if s.startswith("'") and s.endswith("'"):
        return s[1:-1].replace("''", "'")
    lo=s.lower()
    if lo in ('true','yes','on'):return True
    if lo in ('false','no','off'):return False
    if lo in ('null','~'):return None
    try:
        if re.fullmatch(r'[+-]?\d+',s):return int(s,10)
        if re.fullmatch(r'[+-]?(?:\d+\.\d*|\.\d+)(?:[eE][+-]?\d+)?',s):return float(s)
    except ValueError:pass
    if s.startswith(('[','{')):
        try:return json.loads(s)
        except ValueError:pass
    return s

def _yaml(text):
    root={}; stack=[(-1,root)]
    for line in text.splitlines():
        if not line.strip() or line.lstrip().startswith('#'):continue
        indent=len(line)-len(line.lstrip(' ')); body=line.strip()
        if ':' not in body:continue
        key,val=body.split(':',1); key=key.strip().strip('"\''); val=val.strip()
        while stack and indent<=stack[-1][0]:stack.pop()
        parent=stack[-1][1]
        if not isinstance(parent,dict):continue
        if val:
            # Trim comments outside quotes, as YAML comments begin after whitespace.
            if ' #' in val:val=val.split(' #',1)[0].rstrip()
            parent[key]=_scalar(val)
        else:
            obj={};parent[key]=obj;stack.append((indent,obj))
    return root

def _toml(text):
    root={}; current=root
    for line in text.splitlines():
        line=line.strip()
        if not line or line.startswith('#'):continue
        if line.startswith('[') and line.endswith(']'):
            current=root
            for component in line[1:-1].split('.'):
                component=component.strip().strip('"\'')
                current=current.setdefault(component,{})
                if not isinstance(current,dict):break
            continue
        if '=' in line:
            k,v=line.split('=',1); k=k.strip().strip('"\'')
            if '#' in v and not any(q in v for q in ('"',"'")):v=v.split('#',1)[0]
            current[k]=_scalar(v)
    return root

def load_data(source_dir):
    result={}
    if not os.path.isdir(source_dir):return result
    for root,dirs,files in os.walk(source_dir):
        dirs.sort()
        for name in sorted(files):
            path=os.path.join(root,name)
            try:
                with open(path,encoding='utf-8') as f:text=f.read()
                if name.startswith('.chezmoidata.') and name.endswith('.json'): value=json.loads(text)
                elif name.startswith('.chezmoidata.') and name.endswith(('.yaml','.yml')):value=_yaml(text)
                elif name.startswith('.chezmoidata.') and name.endswith('.toml'):value=_toml(text)
                else:continue
            except (OSError,ValueError):continue
            if isinstance(value,dict):result.update(value)
    return result
