          "run_once_", "run_onchange_", "run_before_", "run_after_", "run_")

def _source_metadata(name):
    return name in (".chezmoiignore", ".chezmoi.toml", ".chezmoi.toml.tmpl") or name.startswith(".chezmoidata.")


def target_name(name):
    # Attributes are source-state prefixes and are stripped in the target.
    changed = True
    while changed:
        changed = False
        for prefix in _ATTRS:
            if prefix.strip() and name.startswith(prefix.strip()):
                name = name[len(prefix.strip()):]
                changed = True
    if name.startswith("dot_"):
        name = "." + name[4:]
    if name.endswith(".tmpl"):
        name = name[:-5]
    return name


def _managed(source):
    result = set()
    root = Path(source)
    if not root.is_dir():
        return result
    for base, dirs, files in os.walk(root):
        dirs[:] = [d for d in dirs if d != ".git"]
        relbase = Path(base).relative_to(root)
        for name in dirs + files:
            if _source_metadata(name):
                continue
            # Run scripts are source-state actions, not destination entries.
            if name in files and name.startswith("run_"):
                continue
            rel = Path(*(target_name(part) for part in relbase.parts), target_name(name)).as_posix()
            result.add(rel)
    return result


def _ignored_patterns(source):
    p = Path(source) / ".chezmoiignore"
    try:
        return [x.strip() for x in p.read_text().splitlines()
                if x.strip() and not x.lstrip().startswith("#")]
    except OSError:
        return []


def _tree_lines(paths):
    root = {}
    terminal = object()
    for path in paths:
        node = root
        for part in path.split("/"):
            node = node.setdefault(part, {})
        node[terminal] = None
    lines = []
    def walk(node, depth):
        for key in sorted((k for k in node if k is not terminal)):
            lines.append("  " * depth + key)
            walk(node[key], depth + 1)
    walk(root, 0)
    return lines


